CREATE SCHEMA "ffb";

CREATE TYPE "ffb"."gender" AS ENUM ('M', 'F');
CREATE TYPE "ffb"."model_type" AS ENUM ('Caster', 'Leader', 'Standard');
CREATE TYPE "ffb"."model_stat_type" AS ENUM ('Hero', 'Follower');
CREATE TYPE "ffb"."skill_type" AS ENUM ('general');
CREATE TYPE "ffb"."weapon_group" AS ENUM ('unknown','model-specific');
CREATE TYPE "ffb"."shield_type" AS ENUM ('AN', 'AS', 'B', 'L', 'P', 'S');

CREATE TABLE "ffb"."melee_weapons" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" text NOT NULL,
  "damage" integer NOT NULL CHECK ("damage" >= 0),
  "weapon_group" "ffb"."weapon_group" NOT NULL
);

CREATE TABLE "ffb"."range_weapons" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" text NOT NULL,
  "damage" integer NOT NULL CHECK ("damage" >= 0),
  "distance" integer NOT NULL CHECK ("distance" >= 0),
  "weapon_group" "ffb"."weapon_group" NOT NULL
);

CREATE TABLE "ffb"."model_melee_weapons" (
  "modelid" integer NOT NULL,
  "weaponid" integer NOT NULL,
  "rating" integer NOT NULL CHECK ("rating" >= 0)
);

CREATE TABLE "ffb"."model_range_weapons" (
  "modelid" integer NOT NULL,
  "weaponid" integer NOT NULL,
  "rating" integer NOT NULL CHECK ("rating" >= 0)
);

CREATE TABLE "ffb"."factions" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" text NOT NULL UNIQUE
);

CREATE TABLE "ffb"."model_factions" (
  "factionid" integer NOT NULL,
  "modelid" integer NOT NULL,
  PRIMARY KEY ("modelid", "factionid")
);

CREATE TABLE "ffb"."model_primaryfactions" (
  "factionid" integer NOT NULL,
  "modelid" integer NOT NULL,
  PRIMARY KEY ("modelid", "factionid")
);

CREATE TABLE "ffb"."model_trustedfactions" (
  "factionid" integer NOT NULL,
  "modelid" integer NOT NULL,
  PRIMARY KEY ("modelid", "factionid")
);

CREATE TABLE "ffb"."talents" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" text NOT NULL UNIQUE
);

CREATE TABLE "ffb"."talent_types" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" text NOT NULL UNIQUE
);

CREATE TABLE "ffb"."advancement_talents" (
  "talentid" integer NOT NULL,
  "typeid" integer NOT NULL,
  PRIMARY KEY ("talentid", "typeid")
);

CREATE TABLE "ffb"."skills" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" text NOT NULL UNIQUE,
  "skill_type" "ffb"."skill_type" NOT NULL
);

CREATE TABLE "ffb"."model_skills" (
  "modelid" integer NOT NULL,
  "skillid" integer NOT NULL,
  "rating" integer NOT NULL CHECK ("rating" >= 0),
  PRIMARY KEY ("modelid", "skillid")
);

CREATE TABLE "ffb"."models" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" text NOT NULL,
  "displayname" text NOT NULL,
  "model_type" "ffb"."model_type" NOT NULL,
  "gender" "ffb"."gender" NOT NULL,
  "value" integer NOT NULL CHECK ("value" >= 0),
  "race" text NOT NULL,
  "armor" integer NOT NULL CHECK ("armor" >= 0),
  "discipline" integer NOT NULL CHECK ("discipline" >= 0),
  "shield" "ffb"."shield_type",
  "agility" integer CHECK ("agility" >= 0),
  "dexterity" integer CHECK ("dexterity" >= 0),
  "endurance" integer CHECK ("endurance" >= 0),
  "knowledge" integer CHECK ("knowledge" >= 0),
  "spirit" integer CHECK ("spirit" >= 0),
  "strength" integer CHECK ("strength" >= 0),
  "speed" integer NOT NULL CHECK ("speed" >= 0),
  "stat_type" "ffb"."model_stat_type" NOT NULL
);

CREATE TABLE "ffb"."model_talents" (
  "modelid" integer NOT NULL,
  "talentid" integer NOT NULL
);

CREATE TYPE "ffb"."casting_type" AS ENUM ('energy', 'spirit', 'sorcery');

CREATE TABLE "ffb"."model_casting" (
  "modelid" integer NOT NULL PRIMARY KEY,
  "name" text NOT NULL,
  "power" integer NOT NULL CHECK ("power" >= 0),
  "rating" integer NOT NULL CHECK ("rating" >= 0),
  "type" "ffb"."casting_type" NOT NULL
);

CREATE TABLE "ffb"."model_performance" (
  "modelid" integer NOT NULL PRIMARY KEY,
  "name" text NOT NULL,
  "rating" integer NOT NULL CHECK ("rating" >= 0)
);

CREATE TABLE "ffb"."model_focus" (
  "modelid" integer NOT NULL PRIMARY KEY,
  "name" text NOT NULL,
  "rating" integer NOT NULL CHECK ("rating" >= 0)
);

CREATE TABLE "ffb"."model_options" (
  "modelid" integer NOT NULL,
  "name" text NOT NULL,
  "rating" integer,
  PRIMARY KEY ("modelid", "name")
);

CREATE TABLE "ffb"."model_veterans" (
  "modelid" integer NOT NULL,
  "name" text NOT NULL,
  "cost" integer NOT NULL CHECK ("cost" >= 0),
  "rating" integer,
  PRIMARY KEY ("modelid", "name")
);

ALTER TABLE "ffb"."model_talents" ADD FOREIGN KEY ("modelid") REFERENCES "ffb"."models" ("id") ON DELETE CASCADE;
ALTER TABLE "ffb"."model_talents" ADD FOREIGN KEY ("talentid") REFERENCES "ffb"."talents" ("id") ON DELETE CASCADE;

ALTER TABLE "ffb"."advancement_talents" ADD FOREIGN KEY ("typeid") REFERENCES "ffb"."talent_types" ("id") ON DELETE CASCADE;
ALTER TABLE "ffb"."advancement_talents" ADD FOREIGN KEY ("talentid") REFERENCES "ffb"."talents" ("id") ON DELETE CASCADE;

ALTER TABLE "ffb"."model_factions" ADD FOREIGN KEY ("modelid") REFERENCES "ffb"."models" ("id") ON DELETE CASCADE;
ALTER TABLE "ffb"."model_primaryfactions" ADD FOREIGN KEY ("modelid") REFERENCES "ffb"."models" ("id") ON DELETE CASCADE;
ALTER TABLE "ffb"."model_trustedfactions" ADD FOREIGN KEY ("modelid") REFERENCES "ffb"."models" ("id") ON DELETE CASCADE;

ALTER TABLE "ffb"."model_factions" ADD FOREIGN KEY ("factionid") REFERENCES "ffb"."factions" ("id") ON DELETE CASCADE;
ALTER TABLE "ffb"."model_primaryfactions" ADD FOREIGN KEY ("factionid") REFERENCES "ffb"."factions" ("id") ON DELETE CASCADE;
ALTER TABLE "ffb"."model_trustedfactions" ADD FOREIGN KEY ("factionid") REFERENCES "ffb"."factions" ("id") ON DELETE CASCADE;

ALTER TABLE "ffb"."model_melee_weapons" ADD FOREIGN KEY ("weaponid") REFERENCES "ffb"."melee_weapons" ("id") ON DELETE CASCADE;
ALTER TABLE "ffb"."model_melee_weapons" ADD FOREIGN KEY ("modelid") REFERENCES "ffb"."models" ("id") ON DELETE CASCADE;

ALTER TABLE "ffb"."model_range_weapons" ADD FOREIGN KEY ("weaponid") REFERENCES "ffb"."range_weapons" ("id") ON DELETE CASCADE;
ALTER TABLE "ffb"."model_range_weapons" ADD FOREIGN KEY ("modelid") REFERENCES "ffb"."models" ("id") ON DELETE CASCADE;

ALTER TABLE "ffb"."model_skills" ADD FOREIGN KEY ("skillid") REFERENCES "ffb"."skills" ("id") ON DELETE CASCADE;
ALTER TABLE "ffb"."model_skills" ADD FOREIGN KEY ("modelid") REFERENCES "ffb"."models" ("id") ON DELETE CASCADE;

ALTER TABLE "ffb"."model_casting" ADD FOREIGN KEY ("modelid") REFERENCES "ffb"."models" ("id") ON DELETE CASCADE;
ALTER TABLE "ffb"."model_performance" ADD FOREIGN KEY ("modelid") REFERENCES "ffb"."models" ("id") ON DELETE CASCADE;
ALTER TABLE "ffb"."model_focus" ADD FOREIGN KEY ("modelid") REFERENCES "ffb"."models" ("id") ON DELETE CASCADE;
ALTER TABLE "ffb"."model_options" ADD FOREIGN KEY ("modelid") REFERENCES "ffb"."models" ("id") ON DELETE CASCADE;
ALTER TABLE "ffb"."model_veterans" ADD FOREIGN KEY ("modelid") REFERENCES "ffb"."models" ("id") ON DELETE CASCADE;

CREATE INDEX "idx_model_melee_weapons_weaponid" ON "ffb"."model_melee_weapons" ("weaponid");
CREATE INDEX "idx_model_range_weapons_weaponid" ON "ffb"."model_range_weapons" ("weaponid");
CREATE INDEX "idx_model_skills_skillid" ON "ffb"."model_skills" ("skillid");
CREATE INDEX "idx_model_talents_talentid" ON "ffb"."model_talents" ("talentid");
CREATE INDEX "idx_model_factions_factionid" ON "ffb"."model_factions" ("factionid");
CREATE INDEX "idx_model_primaryfactions_factionid" ON "ffb"."model_primaryfactions" ("factionid");
CREATE INDEX "idx_model_trustedfactions_factionid" ON "ffb"."model_trustedfactions" ("factionid");
CREATE INDEX "idx_advancement_talents_typeid" ON "ffb"."advancement_talents" ("typeid");
CREATE INDEX "idx_advancement_talents_talentid" ON "ffb"."advancement_talents" ("talentid");

